<script setup lang="ts">
import {useAccountingAlerts} from './useAccountingAlerts';
import {useAccountingLiveRefresh} from './workspaceRealtime';
import {ref,computed,watch} from 'vue';
import AccountingSelect from './AccountingSelect.vue';
import {useAccountingPermissions} from './permissions';
const props=defineProps<{company:number;section:string;title:string;accounts:any[]}>(),can=useAccountingPermissions();
const today=new Date().toLocaleDateString('en-CA'),from=ref(today.slice(0,8)+'01'),to=ref(today),account=ref(''),party=ref(''),page=ref(1),result=ref<any>(null),busy=ref(false),exporting=ref(false),error=ref('');let generation=0;const applied=ref<Record<string,string>>({});
const aged=computed(()=>props.section.startsWith('aged-')),sales=computed(()=>props.section==='sales-report'),people=computed(()=>props.section==='customer-ledger'||props.section==='supplier-ledger'),parties=ref<any[]>([]);
const options=computed(()=>props.accounts.filter(a=>!a.is_group&&(props.section==='cash-book'?a.account_type==='Cash':props.section==='bank-book'?a.account_type==='Bank':props.section==='income-report'?a.root_type==='Income':props.section==='expense-report'?a.root_type==='Expense':props.section==='customer-ledger'?a.account_type==='Receivable':props.section==='supplier-ledger'?a.account_type==='Payable':true)));
const rows=computed(()=>aged.value?result.value?.rows||[]:result.value?.entries?.data||[]),last=computed(()=>aged.value?result.value?.last_page||1:result.value?.entries?.last_page||1);
const money=(n:any)=>Number(n||0).toLocaleString('en-PK',{minimumFractionDigits:2,maximumFractionDigits:2});
const companyName=computed(()=>props.accounts[0]?.company_name||'');
const totalRows=computed(()=>aged.value?result.value?.total||0:result.value?.entries?.total||0);
const cards=computed(()=>{
 const r=result.value;if(!r)return [];
 if(aged.value)return [{label:'Total outstanding',value:r.summary.outstanding},{label:'Not overdue',value:r.summary.current},{label:'1?30 days overdue',value:r.summary.days_1_30},{label:'31?60 days overdue',value:r.summary.days_31_60},{label:'61?90 days overdue',value:r.summary.days_61_90},{label:'Over 90 days',value:r.summary.over_90}];
 if(sales.value)return [{label:'Invoiced sales ? including tax',value:r.total},{label:'Posted invoices',value:String(totalRows.value),count:true}];
 if(props.section==='income-report')return [{label:'Income credits',value:r.credit},{label:'Debits / adjustments',value:r.debit},{label:'Net income in period',value:String(Number(r.credit)-Number(r.debit))}];
 if(props.section==='expense-report')return [{label:'Expense debits',value:r.debit},{label:'Credits / adjustments',value:r.credit},{label:'Net expense in period',value:String(Number(r.debit)-Number(r.credit))}];
 return [{label:'Opening balance',value:r.opening},{label:'Period debit',value:r.debit},{label:'Period credit',value:r.credit},{label:'Closing balance',value:r.closing}];
});
function balance(n:any){const value=Number(n||0);return money(Math.abs(value))+(value>0?' Dr':value<0?' Cr':'');}
function params(){return new URLSearchParams({company_id:String(props.company),report:props.section,from:aged.value?'1900-01-01':from.value,to:to.value,page:String(page.value),...(account.value?{account_id:account.value}:{}),...(party.value?{party_id:party.value}:{})});}
async function load(reset=false){if(reset)page.value=1;const token=++generation;busy.value=true;error.value='';try{const filters=!reset&&Object.keys(applied.value).length?new URLSearchParams({...applied.value,page:String(page.value)}):params();const r=await fetch('/accounting/api/reports?'+filters,{headers:{Accept:'application/json'}}),d=await r.json();if(!r.ok)throw Error(Object.values(d.errors||{}).flat().join(' ')||d.message);if(token===generation){result.value=d;const saved:Record<string,string>={};filters.forEach((value,key)=>saved[key]=value);applied.value=saved;}}catch(e:any){if(token===generation){error.value=e.message;result.value=null;}}finally{if(token===generation)busy.value=false;}}
async function download(){if(exporting.value)return;exporting.value=true;error.value='';try{const q=new URLSearchParams(applied.value);q.set('export','csv');const r=await fetch('/accounting/api/reports?'+q);if(!r.ok)throw Error('Unable to export this report.');const url=URL.createObjectURL(await r.blob()),a=document.createElement('a');a.href=url;a.download=props.section+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}catch(e:any){error.value=e.message;}finally{exporting.value=false;}}
watch(()=>[props.company,props.section],async()=>{account.value='';party.value='';parties.value=[];applied.value={};const company=props.company,section=props.section;void load(true);if(people.value){try{const r=await fetch('/accounting/api/report-parties?company_id='+company+'&report='+section,{headers:{Accept:'application/json'}});const d=await r.json();if(r.ok&&company===props.company&&section===props.section)parties.value=d.data;}catch{}}},{immediate:true});
useAccountingLiveRefresh(()=>load(),()=>true);
useAccountingAlerts(error);
</script>
<template><section class="ar-report">
<header class="ar-heading"><div><span class="ar-eyebrow">Accounting / Reports</span><h2>{{title}}</h2><p class="muted">{{aged?'Outstanding invoice aging by due date.':sales?'Posted sales invoices, after discounts and including tax.':people?'Customer and supplier movements from the posted ledger.':'Posted account movements with period totals.'}}</p></div><button v-if="can('reports.export')" class="button" type="button" :disabled="busy||exporting||!result" @click="download"><span v-if="exporting" class="ac-spinner"></span>{{exporting?'Preparing export...':'Download CSV'}}</button></header>
<form class="ar-filters" @submit.prevent="load(true)"><label v-if="!aged">From<input v-model="from" type="date" required></label><label>{{aged?'As of date':'To'}}<input v-model="to" type="date" :min="aged?undefined:from" required></label><label v-if="!aged&&!sales">Ledger account<AccountingSelect><select v-model="account"><option value="">All matching accounts</option><option v-for="a in options" :key="a.id" :value="a.id">{{a.code}} - {{a.name}}</option></select></AccountingSelect></label><label v-if="people">{{section==='customer-ledger'?'Customer':'Supplier'}}<AccountingSelect><select v-model="party"><option value="">All contacts</option><option v-for="p in parties" :key="p.id" :value="p.id">{{p.name}}</option></select></AccountingSelect></label><button class="button primary" :disabled="busy"><span v-if="busy" class="ac-spinner"></span>{{busy?'Loading...':'Update report'}}</button></form>
<p v-if="error" class="notice admin-error" role="alert">{{error}}</p><div v-if="busy" class="ar-loading" role="status"><span class="ac-spinner"></span> Preparing report...</div>
<template v-if="result&&!busy"><div class="ar-summary"><article v-for="card in cards" :key="card.label"><span>{{card.label}}</span><strong>{{card.count?card.value:money(card.value)}}</strong><small>{{card.count?'Matching records':result.currency}}</small></article></div>
<div class="ar-statement"><header class="ar-statement-heading"><div><span class="ar-eyebrow">Financial report</span><h3>{{title}}</h3><p>{{aged?'As of '+applied.to:applied.from+' to '+applied.to}}</p></div><span class="ar-currency">{{result.currency}} ? Posted only</span></header>
<p class="ar-note">{{aged?'Aging uses invoice due dates. Unallocated journal adjustments are not invoice settlements.':sales?'Draft invoices are excluded. Invoices reversed by the report end date are excluded.':'Balances are debit-positive. Dr = debit balance; Cr = credit balance. Draft entries are excluded.'}}</p>
<div class="ac-table-wrap ar-table"><table class="ac-finance-table"><thead><tr v-if="aged"><th>Invoice</th><th>Contact</th><th>Due date</th><th class="numeric">Days overdue</th><th class="numeric">Outstanding</th></tr><tr v-else-if="sales"><th>Invoice</th><th>Customer</th><th>Date</th><th>Due date</th><th class="numeric">Total</th></tr><tr v-else><th>Date</th><th>Journal</th><th>Account / Contact</th><th>Description</th><th class="numeric">Debit</th><th class="numeric">Credit</th><th class="numeric">Balance</th></tr></thead><tbody><tr v-for="row in rows" :key="row.id"><template v-if="aged"><td><strong>{{row.number}}</strong></td><td>{{row.party_name}}</td><td>{{row.due_date}}</td><td class="numeric"><span :class="{'ar-overdue':row.overdue_days>0}">{{row.overdue_days}}</span></td><td class="numeric">{{money(row.outstanding)}}</td></template><template v-else-if="sales"><td><strong>{{row.number}}</strong></td><td>{{row.party_name}}</td><td>{{row.posting_date}}</td><td>{{row.due_date}}</td><td class="numeric">{{money(row.total)}}</td></template><template v-else><td class="ar-date">{{row.posting_date}}</td><td><strong>{{row.number}}</strong></td><td><small>{{row.code}}</small>{{row.name}}<small v-if="row.party_name">{{row.party_name}}</small></td><td class="ar-description">{{row.remarks||'?'}}</td><td class="numeric">{{money(row.debit)}}</td><td class="numeric">{{money(row.credit)}}</td><td class="numeric">{{balance(row.balance)}}</td></template></tr><tr v-if="!rows.length"><td colspan="7" class="ar-empty"><strong>No matching posted transactions</strong><p>Try another date range or clear the account/contact filters.</p></td></tr></tbody><tfoot v-if="rows.length"><tr v-if="aged||sales"><th colspan="4">{{aged?'Total outstanding':'Total sales'}} ? all matching records</th><th class="numeric">{{money(aged?result.summary.outstanding:result.total)}}</th></tr><tr v-else><th colspan="4">Period totals ? all matching records</th><th class="numeric">{{money(result.debit)}}</th><th class="numeric">{{money(result.credit)}}</th><th class="numeric">{{balance(result.closing)}}</th></tr></tfoot></table></div>
<footer class="ar-footer"><span>{{totalRows}} records ? Page {{page}} of {{last}}</span><div><button class="button" :disabled="page<=1||busy" @click="page--;load()">Previous</button><button class="button" :disabled="page>=last||busy" @click="page++;load()">Next</button></div></footer></div></template></section></template>
<style scoped>
.ar-report{min-width:0}.ar-heading{display:flex;justify-content:space-between;align-items:center;gap:16px;flex-wrap:wrap;margin-bottom:24px}.ar-heading h2{margin:7px 0}.ar-heading p{margin:0}.ar-eyebrow{font-size:10px;letter-spacing:.09em;text-transform:uppercase;color:var(--muted)}.ar-filters{display:flex;align-items:flex-end;gap:16px;flex-wrap:wrap;padding:20px;border:1px solid var(--line);border-radius:12px;background:var(--surface);margin-bottom:24px}.ar-filters label{display:flex;flex:1 1 160px;min-width:0;flex-direction:column;gap:8px;font-size:12px}.ar-filters input{width:100%;min-width:0}.ar-summary{display:grid;grid-template-columns:repeat(auto-fit,minmax(160px,1fr));gap:14px;margin:0 0 24px}.ar-summary article{padding:18px 20px;border:1px solid var(--line);border-radius:12px;background:var(--surface);display:flex;flex-direction:column;gap:9px}.ar-summary article>span{font-size:12px;color:var(--muted)}.ar-summary strong{font-size:23px;font-variant-numeric:tabular-nums;overflow-wrap:anywhere}.ar-summary small{font-size:10px;color:var(--muted)}.ar-statement{border:1px solid var(--line);border-radius:14px;overflow:hidden;background:var(--surface)}.ar-statement-heading{display:flex;justify-content:space-between;align-items:center;gap:16px;padding:24px;flex-wrap:wrap}.ar-statement-heading h3{font-size:19px;margin:8px 0}.ar-statement-heading p{font-size:12px;color:var(--muted);margin:0}.ar-currency{font-size:11px;border:1px solid var(--line);border-radius:6px;padding:8px 10px}.ar-note{padding:12px 24px;margin:0;border-top:1px solid var(--line);font-size:11px;color:var(--muted)}.ar-table{max-height:560px;overflow:auto}.ar-table table{min-width:720px}.ar-table thead th{position:sticky;top:0;background:var(--surface);z-index:1}.ar-table td,.ar-table th{padding:15px 18px}.ar-table .numeric{text-align:right;white-space:nowrap;font-variant-numeric:tabular-nums}.ar-table td small{display:block;font-size:10px;color:var(--muted);margin:3px 0}.ar-table tfoot th{border-top:2px solid var(--line)}.ar-date{white-space:nowrap}.ar-description{max-width:300px;overflow-wrap:anywhere}.ar-footer{display:flex;justify-content:space-between;align-items:center;gap:16px;flex-wrap:wrap;border-top:1px solid var(--line);padding:16px 24px;font-size:12px;color:var(--muted)}.ar-footer>div{display:flex;gap:8px}.ar-empty{text-align:center!important;padding:45px 20px!important;color:var(--muted)}.ar-empty p{margin:8px 0 0;font-size:12px}.ar-overdue{color:#d97706}.ar-loading{padding:40px;text-align:center;color:var(--muted)}@media(max-width:640px){.ar-filters{padding:16px}.ar-summary{grid-template-columns:repeat(2,minmax(0,1fr))}.ar-summary article{padding:15px}.ar-summary strong{font-size:19px}.ar-statement-heading{padding:18px}}
</style>
